DROP PROCEDURE IF EXISTS p;
DELIMITER //
CREATE PROCEDURE p(IN n INT)
BEGIN
  DECLARE i INT DEFAULT 0;
  WHILE i < n DO
    SET i = i + 1;
  END WHILE;
  SELECT i;
END //
CREATE TRIGGER trg BEFORE INSERT ON t FOR EACH ROW
BEGIN
  SET NEW.created = NOW();
END//
DELIMITER ;
CALL p(3);
delimiter $$
SELECT 1; SELECT 2$$
